/**
 * R5 (gates-perf W0a; fix round 3): can a wall-clock or GPU-timer number be attributed to the
 * build? Read in NODE at the moment a row's assert is handed to the page (A9 and A21 are getters).
 * Quiet = R26's test (1-minute load average < 3) AND no OTHER headless gate Chrome alive (a gate
 * Chrome's main process carries --remote-debugging; this runner's own Chrome is its child). The
 * GPU timer measures our command stream's elapsed time on a GPU every other Chrome shares, so a
 * null frame that fits inside one time slice does not prove a 50 ms frame was not preempted.
 */
function boxContention() {
  const load = os.loadavg().map((v) => +v.toFixed(2));
  let otherGateChromes = null;
  try {
    const ps = spawnSync('ps', ['-axww', '-o', 'pid=,ppid=,command='], { encoding: 'utf8', maxBuffer: 32 * 1024 * 1024 }).stdout || '';
    otherGateChromes = ps.split('\n').filter((l) => /Chrome for Testing|chrome-headless-shell/.test(l) && !/--type=/.test(l)
      && /--remote-debugging/.test(l) && !new RegExp('^\\s*\\d+\\s+' + process.pid + '\\s').test(l)).length;
  } catch { otherGateChromes = null; }
  return { load, otherGateChromes, quiet: load[0] < 3 && otherGateChromes === 0, at: new Date().toISOString() };
}

