            // of a metre of travel — a real skate measurement, not a lowered bar
            if (w.n >= 3) { if (w.bad) hitched++; else done.push(+Math.hypot(w.x1 - w.x0, w.z1 - w.z0).toFixed(4)); }
            open[f.name] = null;
