  var MINE = ['siteOf', 'installMemInstrument', 'Object.set', 'rec ', '.rec', 'wrapDispose'];
  function isMine(L) {
    for (var i = 0; i < MINE.length; i++) if (L.indexOf(MINE[i]) >= 0) return true;
    return false;
  }
