    if (fog) {
      if (fog.density !== undefined) fog.density = 0;
      if (fog.far !== undefined) { fog.near = 1e5; fog.far = 1e6; }
    }
    if (ColorCtor) __CTX__.scene.background = new ColorCtor(O.bg ?? 0x8fb3d1);

    const n = cast.length;
    const fov = O.fov ?? 26;
    const D = O.depth ?? 60;
    const BX = 0, BZ = 120;
    const ground = T.getHeight(BX, BZ);
