      if (!Object.keys(out).length) return { pass: null, detail: 'SKIP-R18: no staged kind declares a sizeClass (R24 grades by declared class); unclassified: ' + unclassified.join(', ') };
      const bad = Object.keys(out).filter((k) => !ok(out[k], ...TIER[cls[k]]));
