      const kneeMin = [9, 9], kneeMax = [-9, -9];
      const hip = new V(), knee = new V(), ankle = new V(), sh = new V(), hand = new V();
      const bone = (n, re) => { for (const o of n.byName.values()) if (re.test(o.name)) return o; return null; };

