          // NPC because its origin was 0.65 m under the meadow).
          n.group.position.y = ctx.terrain.getHeight(n.group.position.x, n.group.position.z);
          if (n.state !== 'goto') { n.state = 'goto'; n.gotoThen = 'idle'; n.leg = null; }
