      if (!wounded.alive || wounded.health < 1 - 1e-6) bad.push('wounded colossus finished: health ' + wounded.health);

      // 5. a Sentry still dies to one REAL stab
      prog.setDifficulty('easy');
      const w = get(KIND.sentry);
      if (!w) bad.push('no sentry (' + KIND.sentry + ')');
