/** Roles and places a row's staging asks for, read off its own wrapped strings (for A-carried-suite). */
const requiresOf = (g) => {
  // data properties only: a getter (A9) runs when its gate runs, never at module load
  const own = Object.getOwnPropertyDescriptors(g);
  const text = ['setup', 'assert'].map((k) => own[k] && 'value' in own[k] ? own[k].value : null).filter((s) => typeof s === 'string').join('\n');
  const roles = new Set(), places = new Set();
  for (const m of text.matchAll(/roleSkip\((\[[^\]]*\])\)/g)) for (const r of JSON.parse(m[1])) roles.add(r);
  for (const m of text.matchAll(/placeSkip\((\[[^\]]*\])\)/g)) for (const p of JSON.parse(m[1])) places.add(p);
  return { roles: [...roles], places: [...places] };
};

export const GATES = [];
for (const [file, list] of SOURCES) {
  for (const g of list) {
    // property DESCRIPTORS, not a spread: a row whose assert is a getter (A9 reads the load
    // average when it runs) must keep it, or the value would be frozen at module load
    GATES.push(Object.defineProperties({}, {
      ...Object.getOwnPropertyDescriptors(g),
      ...Object.getOwnPropertyDescriptors({
        lane: 'carried',
        r4Lane: g.lane,
        r4Source: 'tools/' + file,
        absorbedBy: ABSORB_BY_SOURCE[file] || ABSORB_BY_R4LANE[g.lane] || 'orchestrator',
        requires: requiresOf(g),
      }),
    }));
  }
}
